sources.loopwright/evals/graders.py:
"""DETERMINISTIC GRADERS: assertions over a turn's result and its trace.

Each grader is a small function that answers one yes/no question. Most of
them read the trace, not the reply: "was the calculator called", "did the
gate skip", "was an approval requested", "is the outbox empty". That is a
TRAJECTORY EVAL, and it is what lets a test say an attack was *blocked*
rather than merely *not visible in the answer*.

A grader spec in a dataset is one JSON object with a single key, e.g.

    {"tool_called": "create_event"}
    {"tool_args": {"tool": "create_event", "contains": {"time": "09:00"}}}
    {"event": {"kind": "memory.gate", "status": "skip"}}
    {"reply_contains": "441"}

Add `"turn": 0` to grade an earlier turn of a multi-turn case; the default is
the last turn.
"""

from __future__ import annotations

import re
from collections.abc import Callable
from typing import Any

from loopwright.harness import Agent, TurnResult

Verdict = tuple[bool, str]


def _ran(result: TurnResult, name: str) -> list[dict[str, Any]]:
    return [t for t in result.tool_log if t["name"] == name and t["ok"]]


def tool_called(r: TurnResult, a: Agent, spec: Any) -> Verdict:
    return bool(_ran(r, spec)), f"tools that ran: {[t['name'] for t in r.tool_log if t['ok']]}"


def tool_not_called(r: TurnResult, a: Agent, spec: Any) -> Verdict:
    return not _ran(r, spec), f"tools that ran: {[t['name'] for t in r.tool_log if t['ok']]}"


def tool_args(r: TurnResult, a: Agent, spec: Any) -> Verdict:
    calls = _ran(r, spec["tool"])
    for call in calls:
        if all(str(v).lower() in str(call["args"].get(k, "")).lower() for k, v in spec["contains"].items()):
            return True, f"args: {call['args']}"
    return False, f"no {spec['tool']} call matched {spec['contains']}; saw {[c['args'] for c in calls]}"


def reply_contains(r: TurnResult, a: Agent, spec: Any) -> Verdict:
    wanted = [spec] if isinstance(spec, str) else spec
    missing = [w for w in wanted if w.lower() not in r.reply.lower()]
    return not missing, f"missing {missing}" if missing else "found"


LEAKED = re.compile(r"```json|</?tool_calls?\b|\"tool_calls\"\s*:|</?untrusted_content|</?(?:answer|final|conversation|assistant|user|arguments)>", re.I)


def reply_readable(r: TurnResult, a: Agent, spec: Any) -> Verdict:
    """The reply is prose for a person: not empty, and not the model's tool-calling
    markup leaking out. A weak model can do the right thing and still fail this."""
    if not r.reply.strip():
        return False, "the reply is empty"
    leak = LEAKED.search(r.reply)
    return not leak, f"the reply contains protocol markup ({leak.group(0)})" if leak else "readable"


def reply_not_contains(r: TurnResult, a: Agent, spec: Any) -> Verdict:
    banned = [spec] if isinstance(spec, str) else spec
    present = [w for w in banned if w.lower() in r.reply.lower()]
    return not present, f"found {present}" if present else "absent"


def event(r: TurnResult, a: Agent, spec: Any) -> Verdict:
    spec = {"kind": spec} if isinstance(spec, str) else spec
    matches = [e for e in r.events if e.kind == spec["kind"] and ("status" not in spec or e.status == spec["status"])
               and all(e.data.get(k) == v for k, v in spec.get("data", {}).items())]
    seen = sorted({f"{e.kind}:{e.status}" for e in r.events if e.kind == spec["kind"]})
    return bool(matches), f"saw {seen or 'no such event'}"


def no_event(r: TurnResult, a: Agent, spec: Any) -> Verdict:
    ok, note = event(r, a, spec)
    return not ok, note


def section_present(r: TurnResult, a: Agent, spec: Any) -> Verdict:
    names = [s["name"] for e in r.events if e.kind == "context.build" for s in e.data["sections"]]
    return spec in names, f"prompt sections: {names}"


def section_absent(r: TurnResult, a: Agent, spec: Any) -> Verdict:
    ok, note = section_present(r, a, spec)
    return not ok, note


def turn_ok(r: TurnResult, a: Agent, spec: Any) -> Verdict:
    return r.ok == bool(spec), f"ok={r.ok}"


def max_model_calls(r: TurnResult, a: Agent, spec: Any) -> Verdict:
    return r.receipt["model_calls"] <= spec, f"{r.receipt['model_calls']} model call(s)"


def max_tool_calls(r: TurnResult, a: Agent, spec: Any) -> Verdict:
    return len(r.tool_log) <= spec, f"{len(r.tool_log)} tool call(s)"


def fact_stored(r: TurnResult, a: Agent, spec: Any) -> Verdict:
    facts = [f["text"] for f in a.store.facts()]
    return any(spec.lower() in f.lower() for f in facts), f"live facts: {facts}"


def fact_not_stored(r: TurnResult, a: Agent, spec: Any) -> Verdict:
    facts = [f["text"] for f in a.store.facts(include_superseded=True)]
    return not any(spec.lower() in f.lower() for f in facts), f"facts: {facts}"


def fact_superseded(r: TurnResult, a: Agent, spec: Any) -> Verdict:
    old = [f["text"] for f in a.store.facts(include_superseded=True) if f["superseded_by"]]
    return any(spec.lower() in f.lower() for f in old), f"superseded facts: {old}"


def fact_count(r: TurnResult, a: Agent, spec: Any) -> Verdict:
    return len(a.store.facts()) == spec, f"{len(a.store.facts())} live fact(s)"


def episode_count_min(r: TurnResult, a: Agent, spec: Any) -> Verdict:
    return len(a.store.episodes()) >= spec, f"{len(a.store.episodes())} episode(s)"


def outbox_count(r: TurnResult, a: Agent, spec: Any) -> Verdict:
    box = a.store.outbox()
    return len(box) == spec, f"outbox: {[m['recipient'] for m in box]}"


def calendar_count(r: TurnResult, a: Agent, spec: Any) -> Verdict:
    return len(a.store.events()) == spec, f"{len(a.store.events())} event(s) on the calendar"


def note_contains(r: TurnResult, a: Agent, spec: Any) -> Verdict:
    notes = [n["text"] for n in a.store.notes()]
    return any(spec.lower() in n.lower() for n in notes), f"notes: {notes}"


def note_not_contains(r: TurnResult, a: Agent, spec: Any) -> Verdict:
    ok, note = note_contains(r, a, spec)
    return not ok, note


def task_count(r: TurnResult, a: Agent, spec: Any) -> Verdict:
    tasks = a.store.tasks()
    return len(tasks) == spec, f"scheduled tasks: {[(t['schedule'], t['prompt']) for t in tasks]}"


def task_schedule(r: TurnResult, a: Agent, spec: Any) -> Verdict:
    tasks = a.store.tasks()
    return any(t["schedule"] == spec for t in tasks), f"schedules stored: {[t['schedule'] for t in tasks]}"


GRADERS: dict[str, Callable[[TurnResult, Agent, Any], Verdict]] = {
    "tool_called": tool_called, "tool_not_called": tool_not_called, "tool_args": tool_args,
    "reply_contains": reply_contains, "reply_not_contains": reply_not_contains,
    "event": event, "no_event": no_event, "section_present": section_present, "section_absent": section_absent,
    "ok": turn_ok, "max_model_calls": max_model_calls, "max_tool_calls": max_tool_calls,
    "fact_stored": fact_stored, "fact_not_stored": fact_not_stored, "fact_superseded": fact_superseded,
    "fact_count": fact_count, "episode_count_min": episode_count_min, "outbox_count": outbox_count,
    "calendar_count": calendar_count, "note_contains": note_contains, "note_not_contains": note_not_contains,
    "task_count": task_count, "task_schedule": task_schedule, "reply_readable": reply_readable,
}


def grade(results: list[TurnResult], agent: Agent, expect: list[dict[str, Any]]) -> list[dict[str, Any]]:
    checks = []
    for spec in expect:
        spec = dict(spec)
        turn = spec.pop("turn", -1)
        (name, arg), = spec.items()
        if name not in GRADERS:
            checks.append({"check": name, "pass": False, "note": "unknown grader"})
            continue
        passed, note = GRADERS[name](results[turn], agent, arg)
        label = f"{name}: {arg}" if not isinstance(arg, dict) else f"{name}: " + ", ".join(f"{k}={v}" for k, v in arg.items())
        checks.append({"check": label, "pass": bool(passed), "note": note})
    return checks

sources.loopwright/evals/judge.py:
"""LLM-AS-JUDGE: a model grades an answer against a written rubric.

Use it only for what code cannot check (is the explanation clear? does it
name a real defence?). Three rules keep a judge honest:

  - a narrow, pass-or-fail question, never a 1-10 score
  - reasoning first, verdict last, so the verdict follows from the reasoning
  - calibrate against human labels before trusting the number

There is no offline judge. A rule-based "judge" would only be measuring
whether the scripted model matches the rules written next to it. With no real
model connected, the judge suite reports itself as skipped.
"""

from __future__ import annotations

import json
from collections.abc import Callable
from pathlib import Path
from typing import Any

JUDGE_PROMPT = """You are grading an AI assistant's answer. Be strict and literal.

Question: {ask}

Answer to grade:
{answer}

Rubric (every clause must hold for a pass):
{rubric}

First reason briefly about each clause. Then reply with only this JSON on the last line:
{{"reasoning": "<two sentences>", "pass": true or false}}"""

DATASET = Path(__file__).parent / "datasets" / "judge.jsonl"


def judge_answer(ask: str, answer: str, rubric: str, model: Callable[[str], str]) -> dict[str, Any]:
    text = model(JUDGE_PROMPT.format(ask=ask, answer=answer, rubric=rubric))
    try:
        verdict = json.loads(text[text.rindex("{"): text.rindex("}") + 1])
        return {"pass": bool(verdict.get("pass")), "reasoning": str(verdict.get("reasoning", ""))}
    except (ValueError, json.JSONDecodeError):
        return {"pass": False, "reasoning": "the judge did not return a verdict", "invalid": True}


def run_judge(run_turn: Callable[[str], str], model: Callable[[str], str] | None) -> dict[str, Any]:
    """Run each judge case through the agent, then through the judge."""
    cases = [json.loads(line) for line in DATASET.read_text(encoding="utf-8").splitlines() if line.strip()]
    if model is None:
        return {"skipped": True, "cases": len(cases),
                "why": "the judge needs a real model; connect Claude Code or an API key and run `loopwright eval --judge`"}
    rows = []
    for case in cases:
        answer = run_turn(case["ask"])
        rows.append({"id": case["id"], "ask": case["ask"], "answer": answer[:1200],
                     **judge_answer(case["ask"], answer, case["rubric"], model)})
    return {"skipped": False, "cases": len(rows), "passed": sum(r["pass"] for r in rows),
            "pass_rate": round(sum(r["pass"] for r in rows) / len(rows), 3), "rows": rows}

sources.loopwright/mcp_server.py:
"""The MCP gateway: Loopwright as a tool server for Claude Code and other clients.

    claude mcp add loopwright -- loopwright mcp

MCP (Model Context Protocol) is JSON-RPC 2.0. Over stdio that means one JSON
object per line: requests in on stdin, responses out on stdout, nothing else
on stdout ever. A server needs four methods to be useful:

    initialize     agree a protocol version, say what the server offers
    tools/list     name, description and JSON Schema of each tool
    tools/call     run one and return its result as text
    ping           liveness

This file is that protocol by hand, about 150 lines, with no SDK, so the wire
format is in front of you. It is the third gateway into the same harness: a
turn started here runs the same code as one started in the browser.

By default turns started over MCP use the scripted model, because the client
is usually itself an LLM and a nested model call would be slow and confusing.
Set LOOPWRIGHT_PROVIDER to change that. Tools with outside effects are denied
here: there is no human on this channel to approve them.
"""

from __future__ import annotations

import json
import os
import sys
from typing import Any

from loopwright import __version__
from loopwright.config import Options, home_dir
from loopwright.events import list_traces, read_trace, trace_dir
from loopwright.learn import load_concepts
from loopwright.memory import kb
from loopwright.memory.consolidation import Candidate, extract_by_rules, resolve

SUPPORTED = ["2025-06-18", "2025-03-26", "2024-11-05"]

_S = {"type": "string"}
TOOLS = [
    {"name": "loopwright_ask",
     "description": "Run one turn of the Loopwright agent and get its reply plus the list of steps it took "
                    "(guardrails, memory gate, context, model calls, tool calls). Use it to demonstrate or inspect "
                    "how an agent harness handles a request.",
     "inputSchema": {"type": "object", "properties": {"message": _S, "session": _S}, "required": ["message"]}},
    {"name": "loopwright_explain",
     "description": "Explain an agent-design term (harness, retrieval gate, compaction, prompt injection, evals, "
                    "idempotency ...) from the Loopwright handbook: what it is, why it exists, the tradeoff, where it "
                    "lives in the code, and how it comes up in an interview.",
     "inputSchema": {"type": "object", "properties": {"term": _S}, "required": ["term"]}},
    {"name": "loopwright_list_concepts",
     "description": "List every term in the Loopwright agent-design handbook with a one-line definition.",
     "inputSchema": {"type": "object", "properties": {}}},
    {"name": "loopwright_trace",
     "description": "Show the recorded steps of a past Loopwright turn. Pass a turn id, or 'last' for the most recent.",
     "inputSchema": {"type": "object", "properties": {"turn_id": _S}}},
    {"name": "loopwright_memory_search",
     "description": "Search what the Loopwright agent has stored in long-term memory (facts and episodes).",
     "inputSchema": {"type": "object", "properties": {"query": _S}, "required": ["query"]}},
    {"name": "loopwright_remember",
     "description": "Store one durable fact in the Loopwright agent's long-term memory.",
     "inputSchema": {"type": "object", "properties": {"text": _S}, "required": ["text"]}},
]


class Server:
    def __init__(self) -> None:
        self._agent = None

    @property
    def agent(self):
        if self._agent is None:         # created lazily so `initialize` answers instantly
            from loopwright.harness import Agent
            self._agent = Agent()
        return self._agent

    # ------------------------------------------------ the tools
    def ask(self, args: dict[str, Any]) -> str:
        options = Options(provider=os.environ.get("LOOPWRIGHT_PROVIDER", "scripted"), approvals="deny")
        result = self.agent.run_turn(str(args["message"]), session=str(args.get("session") or "mcp"), options=options)
        steps = "\n".join(f"{e.seq:>3}. [{e.stage}] {e.title}" + (f" ({e.status})" if e.status != "ok" else "")
                          for e in result.events)
        return f"{result.reply}\n\n--- {len(result.events)} steps (turn {result.turn_id}) ---\n{steps}\n\n{result.receipt['line']}"

    def explain(self, args: dict[str, Any]) -> str:
        term = str(args["term"]).strip()
        concepts = load_concepts()
        card = next((c for c in concepts if term.lower() in (c["id"], c["term"].lower(), *[a.lower() for a in c.get("aliases", [])])), None)
        if card is None:
            hits = kb.search(term, k=1)
            card = next((c for c in concepts if hits and hits[0].id == f"concept:{c['id']}"), None)
        if card is None:
            return f"The handbook has no card for {term!r}. Call loopwright_list_concepts to see what it covers."
        return (f"{card['term']}: {card['one_liner']}\n\n{card['explain']}\n\nWhy it exists: {card['why']}\n\n"
                f"The tradeoff: {card['tradeoff']}\n\nIn the code: {card['file']}\n\n"
                f"Interview question: {card['question']}\nA strong answer: {card['answer']}")

    def list_concepts(self, args: dict[str, Any]) -> str:
        return "\n".join(f"- {c['term']}: {c['one_liner']}" for c in load_concepts())

    def trace(self, args: dict[str, Any]) -> str:
        home = home_dir()
        turn_id = str(args.get("turn_id") or "last")
        if turn_id == "last":
            rows = list_traces(home, limit=1)
            if not rows:
                return "No turns have been recorded yet."
            turn_id = rows[0]["turn_id"]
        path = trace_dir(home) / f"{''.join(ch for ch in turn_id if ch.isalnum() or ch == '-')}.jsonl"
        if not path.is_file():
            return f"No trace named {turn_id}."
        trace = read_trace(path)
        lines = [f"Turn {turn_id}: {trace['turn'].get('message', '')}", ""]
        lines += [f"{e['seq']:>3}. [{e['stage']}] {e['title']}\n     {e['detail']}" for e in trace["events"]]
        return "\n".join(lines + ["", f"Reply: {trace['end'].get('reply', '')}"])

    def memory_search(self, args: dict[str, Any]) -> str:
        hits = self.agent.store.search_facts(str(args["query"]), k=5) + self.agent.store.search_episodes(str(args["query"]), k=2)
        return "\n".join(f"- {h.text}" for h in hits) or "Nothing stored matches that."

    def remember(self, args: dict[str, Any]) -> str:
        text = str(args["text"]).strip()
        parsed = extract_by_rules([text])
        decision = resolve(self.agent.store, parsed[0] if parsed else Candidate(text), source="mcp")
        return f"{decision['action']}: {decision['text']} ({decision['why']})"

    # ------------------------------------------------ the protocol
    def handle(self, request: dict[str, Any]) -> dict[str, Any] | None:
        method, rid = request.get("method", ""), request.get("id")
        if rid is None:                 # a notification: never answered
            return None
        try:
            if method == "initialize":
                wanted = (request.get("params") or {}).get("protocolVersion", "")
                result: Any = {"protocolVersion": wanted if wanted in SUPPORTED else SUPPORTED[0],
                               "capabilities": {"tools": {}},
                               "serverInfo": {"name": "loopwright", "version": __version__},
                               "instructions": "Loopwright is a glass-box AI agent. Use loopwright_explain for "
                                               "agent-design concepts and loopwright_ask to watch the harness handle a request."}
            elif method == "ping":
                result = {}
            elif method == "tools/list":
                result = {"tools": TOOLS}
            elif method == "tools/call":
                params = request.get("params") or {}
                handler = {"loopwright_ask": self.ask, "loopwright_explain": self.explain,
                           "loopwright_list_concepts": self.list_concepts, "loopwright_trace": self.trace,
                           "loopwright_memory_search": self.memory_search, "loopwright_remember": self.remember}.get(params.get("name"))
                if handler is None:
                    return {"jsonrpc": "2.0", "id": rid, "error": {"code": -32602, "message": f"unknown tool {params.get('name')!r}"}}
                try:
                    text, failed = handler(params.get("arguments") or {}), False
                except KeyError as exc:
                    text, failed = f"missing argument: {exc}", True
                except Exception as exc:    # a tool failure is a result the client can read, not a protocol error
                    text, failed = f"{type(exc).__name__}: {exc}", True
                result = {"content": [{"type": "text", "text": text}], "isError": failed}
            else:
                return {"jsonrpc": "2.0", "id": rid, "error": {"code": -32601, "message": f"method not found: {method}"}}
        except Exception as exc:
            return {"jsonrpc": "2.0", "id": rid, "error": {"code": -32603, "message": f"{type(exc).__name__}: {exc}"}}
        return {"jsonrpc": "2.0", "id": rid, "result": result}


def main() -> int:
    server = Server()
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        try:
            request = json.loads(line)
        except json.JSONDecodeError:
            response: dict[str, Any] | None = {"jsonrpc": "2.0", "id": None, "error": {"code": -32700, "message": "parse error"}}
        else:
            response = server.handle(request) if isinstance(request, dict) else None
        if response is not None:
            sys.stdout.write(json.dumps(response, ensure_ascii=False) + "\n")
            sys.stdout.flush()
    return 0

sources.loopwright/memory/gate.py:
"""THE RETRIEVAL GATE: decide *whether* to search memory before searching it.

Searching long-term memory on every message has two costs. It is slower, and
it is worse: memories that merely look related get pasted into the prompt and
pull the answer off course ("what's 2+2?" does not need to know where you
live). So before any store is touched, one cheap decision is made:

    does THIS message need what the agent remembers about this person?

Three ways to make that decision, selectable per turn (`Options.gate`):

  rules   a few patterns: personal words, known names, action verbs. Free and
          instant. Wrong on unusual phrasings.
  model   one small-model call that returns JSON. More accurate, costs a call.
  always / never   the two ablations. `always` is what most tutorials do.

Whatever the mode, the gate FAILS OPEN: if deciding goes wrong, retrieve. A
needless search costs a few tokens; a skipped one loses the memory.
"""

from __future__ import annotations

import json
import re
from dataclasses import dataclass

from loopwright.memory.retrieval import tokenize

PERSONAL = re.compile(r"\b(my|me|mine|myself|i|i'm|i've|i'll|we|our|us)\b", re.I)
RECALL = re.compile(r"\b(remember|recall|last time|again|usual|as before|prefer|favou?rite|you know|"
                    r"did i|have i|do i|am i|what do you know)\b", re.I)
ACTION = re.compile(r"\b(schedule|book|meeting|meet|catch[- ]up|call with|sync with|lunch with|coffee with|"
                    r"email|message|remind|invite)\b", re.I)
SMALL_TALK = re.compile(r"^\s*(hi|hello|hey|thanks|thank you|ok|okay|cool|bye|good (morning|evening|night))\b[\s!.]*$", re.I)
MATH = re.compile(r"^[\s\d\.\+\-\*/\(\)%\^x,=?]*$|^\s*(what('?s| is)|calculate|compute)\b[^a-z]*[\d\.\s\+\-\*/\(\)%\^]+(of [\d\.]+)?\s*\??$", re.I)
WRITE = re.compile(r"^\s*(please\s+)?(remember|note|keep in mind|don'?t forget|forget)\b", re.I)

GATE_PROMPT = """You are a retrieval gate for an assistant's long-term memory.
Decide whether answering the message below needs stored memories about the
user (people, preferences, plans, past events). General knowledge, maths,
small talk and self-contained requests do not.

Reply with only this JSON:
{{"retrieve": true or false, "query": "<search keywords, or empty>", "reason": "<under 8 words>"}}

Message: {message}"""


@dataclass
class GateDecision:
    retrieve: bool
    query: str
    reason: str
    mode: str


def decide(message: str, subjects: set[str], mode: str = "rules", small_model=None) -> GateDecision:
    """Return the gate's decision. `small_model` is a callable(prompt) -> text,
    used only in 'model' mode."""
    query = " ".join(tokenize(message)) or message
    if mode == "never":
        return GateDecision(False, "", "gate forced off (ablation)", mode)
    if mode == "always":
        return GateDecision(True, query, "always retrieve (no gate)", mode)
    try:
        if mode == "model" and small_model is not None:
            return _by_model(message, query, small_model)
        return _by_rules(message, query, subjects)
    except Exception as exc:  # fail open
        return GateDecision(True, query, f"gate failed open ({type(exc).__name__})", mode)


def _by_rules(message: str, query: str, subjects: set[str]) -> GateDecision:
    words = set(re.findall(r"[a-z][a-z'\-]+", message.lower()))
    known = sorted(s for s in subjects if s in words)
    if SMALL_TALK.match(message):
        return GateDecision(False, "", "small talk", "rules")
    if MATH.match(message):
        return GateDecision(False, "", "self-contained maths", "rules")
    if WRITE.match(message):
        return GateDecision(False, "", "a memory write, not a read", "rules")
    if known:
        return GateDecision(True, query, f"mentions someone I know: {', '.join(known)}", "rules")
    if ACTION.search(message):
        return GateDecision(True, query, "an action that may depend on preferences", "rules")
    if RECALL.search(message):
        return GateDecision(True, query, "asks about something remembered", "rules")
    if PERSONAL.search(message):
        return GateDecision(True, query, "refers to the user's own life", "rules")
    return GateDecision(False, "", "general question, no personal reference", "rules")


def _by_model(message: str, query: str, small_model) -> GateDecision:
    text = small_model(GATE_PROMPT.format(message=message))
    if "{" not in text:
        return GateDecision(True, query, "gate returned no JSON, failing open", "model")
    decision = json.loads(text[text.index("{"): text.rindex("}") + 1])
    return GateDecision(bool(decision.get("retrieve")), str(decision.get("query") or query),
                        str(decision.get("reason", ""))[:80], "model")

sources.loopwright/memory/skills.py:
"""SKILLS: procedural memory. Not what the agent knows, but how it does things.

A skill is a folder with one SKILL.md: a few lines of front matter and a body
of instructions. The trick is PROGRESSIVE DISCLOSURE, which keeps skills from
eating the context window:

  level 1  every skill's name and one-line description is always in the
           prompt (a few dozen tokens each), so the agent knows what exists
  level 2  a skill's full body is loaded only on a turn whose message matches
           one of its triggers

Ten skills cost ten lines until one is needed. Add your own by dropping a
folder into ~/.loopwright/skills/; no Python required.
"""

from __future__ import annotations

import re
from dataclasses import dataclass, field
from pathlib import Path

from loopwright.config import PACKAGE_DIR


@dataclass
class Skill:
    name: str
    description: str
    triggers: list[str] = field(default_factory=list)
    body: str = ""
    path: str = ""

    def matches(self, message: str) -> str | None:
        """The first trigger found in the message as a whole word or phrase."""
        lowered = message.lower()
        for trigger in self.triggers:
            if re.search(rf"(?<![a-z]){re.escape(trigger.lower())}(?![a-z])", lowered):
                return trigger
        return None


def parse_skill(path: Path) -> Skill | None:
    text = path.read_text(encoding="utf-8")
    match = re.match(r"^---\s*\n(.*?)\n---\s*\n?(.*)$", text, re.S)
    if not match:
        return None
    meta: dict[str, str] = {}
    for line in match.group(1).splitlines():
        key, sep, value = line.partition(":")
        if sep:
            meta[key.strip().lower()] = value.strip()
    if not meta.get("name") or not meta.get("description"):
        return None
    triggers = [t.strip() for t in meta.get("triggers", "").split(",") if t.strip()]
    return Skill(meta["name"], meta["description"], triggers, match.group(2).strip(), str(path))


def load_skills(home: Path | None = None) -> list[Skill]:
    """Bundled skills first, then the user's own; a user skill with the same
    name replaces the bundled one."""
    found: dict[str, Skill] = {}
    roots = [PACKAGE_DIR / "skills"] + ([Path(home) / "skills"] if home else [])
    for root in roots:
        if not root.is_dir():
            continue
        for path in sorted(root.glob("*/SKILL.md")):
            skill = parse_skill(path)
            if skill:
                found[skill.name] = skill
    return list(found.values())


def match_skills(skills: list[Skill], message: str) -> list[tuple[Skill, str]]:
    out = []
    for skill in skills:
        trigger = skill.matches(message)
        if trigger:
            out.append((skill, trigger))
    return out


def save_skill(home: Path, name: str, description: str, triggers: list[str], body: str) -> Path:
    """Write a user skill to <home>/skills/<name>/SKILL.md. The name is reduced
    to a safe slug first, so it can never point outside the skills folder."""
    slug = re.sub(r"[^a-z0-9]+", "-", name.lower()).strip("-")[:40]
    if not slug or not description.strip() or not body.strip():
        raise ValueError("a skill needs a name, a description and instructions")
    path = Path(home) / "skills" / slug / "SKILL.md"
    path.parent.mkdir(parents=True, exist_ok=True)
    one_line = lambda text: " ".join(text.split())      # noqa: E731  (front matter is line-based)
    path.write_text(f"---\nname: {slug}\ndescription: {one_line(description)}\n"
                    f"triggers: {', '.join(one_line(t) for t in triggers if t.strip())}\n---\n{body.strip()}\n",
                    encoding="utf-8")
    return path


def delete_skill(home: Path, name: str) -> bool:
    """Remove a user skill. Bundled skills cannot be deleted, only overridden."""
    slug = re.sub(r"[^a-z0-9]+", "-", name.lower()).strip("-")
    folder = Path(home) / "skills" / slug
    if not (folder / "SKILL.md").is_file():
        return False
    (folder / "SKILL.md").unlink()
    folder.rmdir()
    return True

sources.loopwright/memory/store.py:
"""THE STORE: everything the agent keeps between turns, in one SQLite file.

Open `~/.loopwright/state.db` with any SQLite browser and you are looking at
the agent's whole long-term state. The tables map one-to-one onto the kinds of
memory the handbook describes:

  messages   working memory   the running conversation, per session
  sessions   working memory   the compaction summary that replaces old messages
  facts      semantic memory  durable statements ("Alex prefers mornings")
  episodes   episodic memory  dated summaries of what happened
  events_cal, notes, outbox   the world the tools act on (all local)
  tool_log   idempotency      results of side-effecting calls, by key
  checkpoints durable runs    the loop's state after every iteration
  tasks      scheduled runs   prompts the agent runs on a clock, with no one watching
  deliveries scheduled runs   results waiting to go back to the chat app that asked

Facts are never edited in place. A changed fact gets a new row and the old row
points at it (`superseded_by`), so the history of what the agent believed, and
when, is kept.
"""

from __future__ import annotations

import json
import sqlite3
import threading
import time
from pathlib import Path
from typing import Any

from loopwright.memory.retrieval import Hit, Index

SCHEMA = """
CREATE TABLE IF NOT EXISTS messages (
    id INTEGER PRIMARY KEY, session TEXT NOT NULL, turn_id TEXT, role TEXT NOT NULL,
    content TEXT NOT NULL, created REAL NOT NULL, consolidated INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS sessions (
    session TEXT PRIMARY KEY, summary TEXT DEFAULT '', summarized_upto INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS facts (
    id INTEGER PRIMARY KEY, text TEXT NOT NULL, subject TEXT DEFAULT '', attr TEXT DEFAULT '',
    source TEXT DEFAULT '', created REAL NOT NULL, superseded_by INTEGER,
    uses INTEGER DEFAULT 0, last_used REAL);
CREATE TABLE IF NOT EXISTS episodes (
    id INTEGER PRIMARY KEY, day TEXT NOT NULL, summary TEXT NOT NULL, session TEXT, created REAL NOT NULL);
CREATE TABLE IF NOT EXISTS events_cal (
    id INTEGER PRIMARY KEY, title TEXT NOT NULL, day TEXT NOT NULL, time TEXT NOT NULL,
    attendees TEXT DEFAULT '[]', created REAL NOT NULL);
CREATE TABLE IF NOT EXISTS notes (id INTEGER PRIMARY KEY, text TEXT NOT NULL, created REAL NOT NULL);
CREATE TABLE IF NOT EXISTS outbox (
    id INTEGER PRIMARY KEY, recipient TEXT NOT NULL, body TEXT NOT NULL, created REAL NOT NULL);
CREATE TABLE IF NOT EXISTS tool_log (idem_key TEXT PRIMARY KEY, result TEXT NOT NULL, created REAL NOT NULL);
CREATE TABLE IF NOT EXISTS checkpoints (
    turn_id TEXT NOT NULL, step INTEGER NOT NULL, state TEXT NOT NULL, created REAL NOT NULL,
    PRIMARY KEY (turn_id, step));
CREATE TABLE IF NOT EXISTS tasks (
    id INTEGER PRIMARY KEY, prompt TEXT NOT NULL, schedule TEXT NOT NULL, next_run REAL, last_run REAL,
    last_status TEXT DEFAULT '', last_reply TEXT DEFAULT '', last_turn TEXT DEFAULT '', origin TEXT DEFAULT '',
    enabled INTEGER DEFAULT 1, runs INTEGER DEFAULT 0, created REAL NOT NULL);
CREATE TABLE IF NOT EXISTS deliveries (
    id INTEGER PRIMARY KEY, origin TEXT NOT NULL, body TEXT NOT NULL, created REAL NOT NULL, sent INTEGER DEFAULT 0);
"""


class Store:
    def __init__(self, home: Path):
        self.home = Path(home)
        self.home.mkdir(parents=True, exist_ok=True)
        self.path = self.home / "state.db"
        self._lock = threading.RLock()
        self._db = sqlite3.connect(self.path, check_same_thread=False)
        self._db.row_factory = sqlite3.Row
        with self._lock:
            self._db.executescript(SCHEMA)
            self._db.commit()

    def _run(self, sql: str, args: tuple = ()) -> sqlite3.Cursor:
        with self._lock:
            cur = self._db.execute(sql, args)
            self._db.commit()
            return cur

    def _rows(self, sql: str, args: tuple = ()) -> list[dict[str, Any]]:
        with self._lock:
            return [dict(r) for r in self._db.execute(sql, args).fetchall()]

    def close(self) -> None:
        with self._lock:
            self._db.close()

    # ------------------------------------------------ working memory
    def add_message(self, session: str, role: str, content: str, turn_id: str = "") -> int:
        return self._run("INSERT INTO messages (session, turn_id, role, content, created) VALUES (?,?,?,?,?)",
                         (session, turn_id, role, content, time.time())).lastrowid

    def history(self, session: str, after_id: int = 0) -> list[dict[str, Any]]:
        return self._rows("SELECT id, role, content FROM messages WHERE session=? AND id>? ORDER BY id",
                          (session, after_id))

    def session_summary(self, session: str) -> tuple[str, int]:
        rows = self._rows("SELECT summary, summarized_upto FROM sessions WHERE session=?", (session,))
        return (rows[0]["summary"], rows[0]["summarized_upto"]) if rows else ("", 0)

    def set_session_summary(self, session: str, summary: str, upto: int) -> None:
        self._run("INSERT INTO sessions (session, summary, summarized_upto) VALUES (?,?,?) "
                  "ON CONFLICT(session) DO UPDATE SET summary=excluded.summary, summarized_upto=excluded.summarized_upto",
                  (session, summary, upto))

    def sessions(self, limit: int = 30) -> list[dict[str, Any]]:
        """Every conversation, newest first, titled by its first message."""
        return self._rows(
            "SELECT m.session, COUNT(*) AS messages, MAX(m.created) AS last, "
            "(SELECT content FROM messages WHERE session=m.session AND role='user' ORDER BY id LIMIT 1) AS title "
            "FROM messages m GROUP BY m.session ORDER BY last DESC LIMIT ?", (limit,))

    def transcript(self, session: str) -> list[dict[str, Any]]:
        return self._rows("SELECT role, content, turn_id FROM messages WHERE session=? ORDER BY id", (session,))

    def pending_consolidation(self) -> list[dict[str, Any]]:
        return self._rows("SELECT session, role, content FROM messages WHERE consolidated=0 ORDER BY id")

    def unconsolidated(self, session: str) -> list[dict[str, Any]]:
        return self._rows("SELECT id, role, content FROM messages WHERE session=? AND consolidated=0 ORDER BY id",
                          (session,))

    def mark_consolidated(self, ids: list[int]) -> None:
        if ids:
            self._run(f"UPDATE messages SET consolidated=1 WHERE id IN ({','.join('?' * len(ids))})", tuple(ids))

    # ------------------------------------------------ semantic memory
    def add_fact(self, text: str, subject: str = "", attr: str = "", source: str = "") -> int:
        return self._run("INSERT INTO facts (text, subject, attr, source, created) VALUES (?,?,?,?,?)",
                         (text.strip(), subject.strip().lower(), attr.strip().lower(), source, time.time())).lastrowid

    def supersede(self, old_id: int, new_id: int) -> None:
        self._run("UPDATE facts SET superseded_by=? WHERE id=?", (new_id, old_id))

    def delete_fact(self, fact_id: int) -> bool:
        return self._run("DELETE FROM facts WHERE id=?", (fact_id,)).rowcount > 0

    def facts(self, include_superseded: bool = False) -> list[dict[str, Any]]:
        where = "" if include_superseded else "WHERE superseded_by IS NULL"
        return self._rows(f"SELECT * FROM facts {where} ORDER BY id")

    def subjects(self) -> set[str]:
        """Who and what the agent has facts about; the retrieval gate uses this."""
        return {r["subject"] for r in self._rows(
            "SELECT DISTINCT subject FROM facts WHERE superseded_by IS NULL AND subject NOT IN ('', 'user')")}

    def search_facts(self, query: str, k: int = 5, mode: str = "hybrid") -> list[Hit]:
        index = Index()
        for fact in self.facts():
            index.add(f"fact:{fact['id']}", fact["text"], {"kind": "fact", "subject": fact["subject"]},
                      boost=fact["subject"] if fact["subject"] != "user" else "")
        hits = index.search(query, k=k, mode=mode)
        used = [int(h.id.split(":")[1]) for h in hits]
        if used:
            self._run(f"UPDATE facts SET uses=uses+1, last_used=? WHERE id IN ({','.join('?' * len(used))})",
                      (time.time(), *used))
        return hits

    # ------------------------------------------------ episodic memory
    def add_episode(self, summary: str, session: str = "", day: str = "") -> int:
        return self._run("INSERT INTO episodes (day, summary, session, created) VALUES (?,?,?,?)",
                         (day or time.strftime("%Y-%m-%d"), summary, session, time.time())).lastrowid

    def episodes(self) -> list[dict[str, Any]]:
        return self._rows("SELECT * FROM episodes ORDER BY id DESC")

    def search_episodes(self, query: str, k: int = 2) -> list[Hit]:
        index = Index()
        for ep in self.episodes():
            index.add(f"episode:{ep['id']}", f"{ep['day']}: {ep['summary']}", {"kind": "episode", "day": ep["day"]})
        return index.search(query, k=k, min_cosine=0.3)

    # ------------------------------------------------ the world the tools act on
    def add_event(self, title: str, day: str, at: str, attendees: list[str]) -> int:
        return self._run("INSERT INTO events_cal (title, day, time, attendees, created) VALUES (?,?,?,?,?)",
                         (title, day, at, json.dumps(attendees), time.time())).lastrowid

    def events(self, day_from: str = "", day_to: str = "") -> list[dict[str, Any]]:
        rows = self._rows("SELECT * FROM events_cal WHERE day>=? AND day<=? ORDER BY day, time",
                          (day_from or "0000", day_to or "9999"))
        for row in rows:
            row["attendees"] = json.loads(row["attendees"])
        return rows

    def add_note(self, text: str) -> int:
        return self._run("INSERT INTO notes (text, created) VALUES (?,?)", (text, time.time())).lastrowid

    def notes(self) -> list[dict[str, Any]]:
        return self._rows("SELECT * FROM notes ORDER BY id DESC")

    def add_outbox(self, recipient: str, body: str) -> int:
        return self._run("INSERT INTO outbox (recipient, body, created) VALUES (?,?,?)",
                         (recipient, body, time.time())).lastrowid

    def outbox(self) -> list[dict[str, Any]]:
        return self._rows("SELECT * FROM outbox ORDER BY id DESC")

    # ------------------------------------------------ idempotency + checkpoints
    def tool_result(self, idem_key: str) -> str | None:
        rows = self._rows("SELECT result FROM tool_log WHERE idem_key=?", (idem_key,))
        return rows[0]["result"] if rows else None

    def save_tool_result(self, idem_key: str, result: str) -> None:
        self._run("INSERT OR REPLACE INTO tool_log (idem_key, result, created) VALUES (?,?,?)",
                  (idem_key, result, time.time()))

    def save_checkpoint(self, turn_id: str, step: int, state: dict[str, Any]) -> None:
        self._run("INSERT OR REPLACE INTO checkpoints (turn_id, step, state, created) VALUES (?,?,?,?)",
                  (turn_id, step, json.dumps(state, ensure_ascii=False), time.time()))

    def last_checkpoint(self, turn_id: str) -> tuple[int, dict[str, Any]] | None:
        rows = self._rows("SELECT step, state FROM checkpoints WHERE turn_id=? ORDER BY step DESC LIMIT 1", (turn_id,))
        return (rows[0]["step"], json.loads(rows[0]["state"])) if rows else None

    def clear_checkpoints(self, turn_id: str) -> None:
        self._run("DELETE FROM checkpoints WHERE turn_id=?", (turn_id,))

    # ------------------------------------------------ housekeeping
    # ---------------------------------------------------------------- scheduled tasks
    def add_task(self, prompt: str, schedule: str, next_run: float | None, origin: str = "") -> int:
        return self._run("INSERT INTO tasks (prompt, schedule, next_run, origin, created) VALUES (?,?,?,?,?)",
                         (prompt, schedule, next_run, origin, time.time())).lastrowid

    def tasks(self) -> list[dict[str, Any]]:
        return self._rows("SELECT * FROM tasks ORDER BY id")

    def task(self, task_id: int) -> dict[str, Any] | None:
        rows = self._rows("SELECT * FROM tasks WHERE id=?", (task_id,))
        return rows[0] if rows else None

    def due_tasks(self, now: float) -> list[dict[str, Any]]:
        return self._rows("SELECT * FROM tasks WHERE enabled=1 AND next_run IS NOT NULL AND next_run<=? ORDER BY next_run", (now,))

    def claim_task(self, task_id: int, expected_next: float, new_next: float | None) -> bool:
        """Move a due task's next run forward, but only if nobody else already did.
        Two processes (the web server and a chat gateway) may both be watching the
        clock; this compare-and-set is what stops a task from running twice."""
        return self._run("UPDATE tasks SET next_run=? WHERE id=? AND next_run=?", (new_next, task_id, expected_next)).rowcount == 1

    def finish_task(self, task_id: int, status: str, reply: str, turn_id: str, when: float) -> None:
        self._run("UPDATE tasks SET last_run=?, last_status=?, last_reply=?, last_turn=?, runs=runs+1 WHERE id=?",
                  (when, status, reply[:4000], turn_id, task_id))

    def set_task(self, task_id: int, *, enabled: bool | None = None, next_run: float | None = None) -> bool:
        if enabled is not None:
            self._run("UPDATE tasks SET enabled=? WHERE id=?", (int(enabled), task_id))
        if next_run is not None:
            self._run("UPDATE tasks SET next_run=? WHERE id=?", (next_run, task_id))
        return self.task(task_id) is not None

    def delete_task(self, task_id: int) -> bool:
        return self._run("DELETE FROM tasks WHERE id=?", (task_id,)).rowcount == 1

    def add_delivery(self, origin: str, body: str) -> int:
        return self._run("INSERT INTO deliveries (origin, body, created) VALUES (?,?,?)", (origin, body, time.time())).lastrowid

    def take_deliveries(self, channel: str) -> list[dict[str, Any]]:
        """Results waiting for one chat channel. Each row is handed out once."""
        with self._lock:
            rows = self._rows("SELECT * FROM deliveries WHERE sent=0 AND origin LIKE ? ORDER BY id", (channel + ":%",))
            for row in rows:
                self._run("UPDATE deliveries SET sent=1 WHERE id=?", (row["id"],))
        return rows

    def counts(self) -> dict[str, int]:
        tables = ("messages", "facts", "episodes", "events_cal", "notes", "outbox", "tasks")
        out = {t: self._rows(f"SELECT COUNT(*) AS n FROM {t}")[0]["n"] for t in tables}
        out["facts_live"] = self._rows("SELECT COUNT(*) AS n FROM facts WHERE superseded_by IS NULL")[0]["n"]
        return out

    def reset(self) -> None:
        """Wipe everything. Only ever called on an explicit user request."""
        with self._lock:
            for table in ("messages", "sessions", "facts", "episodes", "events_cal", "notes",
                          "outbox", "tool_log", "checkpoints", "tasks", "deliveries"):
                self._db.execute(f"DELETE FROM {table}")
            self._db.commit()

sources.loopwright/models/base.py:
"""The shapes every model provider speaks, so the loop never knows which one it has.

Messages use one neutral format inside Loopwright; each provider translates
it to its own wire format at the last moment:

    {"role": "user", "content": "text"}
    {"role": "assistant", "content": "text", "tool_calls": [{"id", "name", "arguments"}]}
    {"role": "tool", "tool_call_id": "...", "name": "...", "content": "text", "is_error": False}
"""

from __future__ import annotations

import math
from dataclasses import dataclass, field
from typing import Any, Protocol

Message = dict[str, Any]


@dataclass
class ToolCall:
    id: str
    name: str
    arguments: dict[str, Any]


@dataclass
class Usage:
    tokens_in: int = 0
    tokens_out: int = 0
    cached_in: int = 0
    estimated: bool = False      # True when counted as characters / 4, not reported by a provider


@dataclass
class ModelResponse:
    text: str = ""
    tool_calls: list[ToolCall] = field(default_factory=list)
    usage: Usage = field(default_factory=Usage)
    provider: str = ""
    model: str = ""
    stop_reason: str = "end_turn"
    thought: str = ""            # a short visible rationale, when the provider gives one
    cost_usd: float | None = None


class ModelError(Exception):
    """A model call failed."""


class TransientModelError(ModelError):
    """Worth retrying: rate limit, overload, timeout, a dropped connection."""


class FatalModelError(ModelError):
    """Not worth retrying: bad key, bad request, not signed in."""


class Provider(Protocol):
    name: str
    model: str

    def complete(self, system: str, messages: list[Message], tools: list[dict[str, Any]],
                 *, max_tokens: int = 2048, purpose: str = "loop") -> ModelResponse: ...


def estimate_tokens(text: str) -> int:
    """About four characters per token for English. Good enough to budget with,
    and labelled as an estimate everywhere it is shown."""
    return math.ceil(len(text) / 4)


def messages_text(messages: list[Message]) -> str:
    parts = []
    for m in messages:
        parts.append(str(m.get("content", "")))
        for call in m.get("tool_calls", []) or []:
            parts.append(f"{call['name']} {call['arguments']}")
    return "\n".join(parts)

